pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // owner is address(0) initially
        // prank a non-owner address
        address nonOwner = address(0x123);
        vm.prank(nonOwner);
        // try to call transferOwnership; should revert in reference but succeed in buggy
        bool ok;
        try c.transferOwnership(nonOwner) { ok = true; } catch { ok = false; }
        assertTrue(!ok);  // reference holds (revert), buggy version breaks (succeeds)
    }
}

