pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1);
        address bob = address(0x2);
        // Initially owner is address(0), set it to alice
        vm.prank(address(0));
        c.transferOwnership(alice);
        // Now alice transfers ownership to herself (no change)
        vm.prank(alice);
        c.transferOwnership(alice);
        // Bob tries to transfer ownership from alice to bob
        vm.prank(bob);
        bool ok;
        try c.transferOwnership(bob) { ok = true; } catch { ok = false; }
        // In reference: reverts, so ok = false, owner stays alice
        // In buggy: reverts after first _ execution sets owner to bob, so ok = false but owner becomes bob
        assertEq(c.owner(), alice);
    }
}

