pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address addr1 = address(0x1);
        address addr2 = address(0x2);

        // Deploy sets owner to address(0). Transfer ownership to addr1.
        c.transferOwnership(addr1);

        // Now from addr1, try to transfer ownership to addr2
        vm.prank(addr1);
        bool ok;
        try c.transferOwnership(addr2) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: only one modifier execution, so the call succeeds (ok = true).
        // Bug version: modifier executes _ twice; after first _ the owner becomes addr2,
        // second _ requires msg.sender == addr2 but msg.sender is addr1 -> revert, so ok = false.
        assertTrue(ok);
    }
}

