pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // owner initially address(0)
        // prank bob, call owned() - should revert because msg.sender != owner
        address bob = address(0x1234);
        vm.prank(bob);
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }
        assertTrue(!ok); // reference: reverts, buggy: also reverts (same modifier) – not divergence yet
        // Now prank address(0) (default caller after vm.stopPrank? Actually we never set prank, so msg.sender = address(this) which is test contract address)
        // We need msg.sender to be address(0) to meet onlyOwner? Owner is address(0), so only address(0) can call transferOwnership
        // vm.prank(address(0)) is not allowed - address(0) cannot be pranked; instead we use address(this) is test contract, not owner.
        // Since owner is address(0), no one can call transferOwnership because msg.sender == owner (address(0)) but only address(0) can be msg.sender which is impossible in prank. So we need a different scenario.
        // Let's redeploy with a known owner: we deploy C manually with a constructor? Actually C has no constructor, owner defaults to 0.
        // We can change owner via owned()? No. So better: use vm.prank(someone) before call to transfer? But modifier onlyOwner requires owner == msg.sender.
        // Alternatively, we can call transferOwnership as address(0) is impossible; but we can use vm.prank(address(this)) after we set owner = address(this).
        // To set owner, we can call owned()? No, owned() does nothing. So we must first call transferOwnership legitimately: the only one who can call it is current owner (address(0)), but that's impossible.
        // Actually address(0) can be msg.sender if the transaction is from a contract with no code? In test, vm.prank(address(0)) is allowed in Foundry? Let's check: vm.prank(address(0)) is allowed - it sets msg.sender to 0.
        // So we use vm.prank(address(0)) to call transferOwnership(bob)
        vm.prank(address(0));
        c.transferOwnership(bob); // reference: owner becomes bob; buggy: owner = msg.sender = address(0)
        // Now assert owner
        assertEq(c.owner(), bob);
    }
}

